base='/app/output/'
def cloud(name):
 m=json.load(open(base+name+'/meta.json'));c='overhead_cam';rgb=np.load(base+name+'/'+c+'_rgb.npy');d=np.load(base+name+'/'+c+'_depth.npy')[-1].astype(float);K=np.array(m['cameras'][c]['intrinsic_cv']);T=np.array(m['cameras'][c]['cam2world_gl']);v,u=np.indices(d.shape);xyz=(T[:3,:3]@np.array([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d]).reshape(3,-1)).T+T[:3,3];return xyz.reshape(240,320,3),rgb

def tips(name):
 xyz,rgb=cloud(name);out={}
 for side in ['left','right']:
  coords=[]
