import sys,numpy as np;sys.path.insert(0,'/app/output');from tips import cloud
for n in ['insert4','nudge_y','insert5']:
 xyz,rgb=cloud(n);print(n)
 for col,m in [('blue',(rgb[:,:,2]>100)&(rgb[:,:,2]>rgb[:,:,1]*1.3)&(rgb[:,:,2]>rgb[:,:,0]*1.5)),('red',(rgb[:,:,0]>120)&(rgb[:,:,0]>rgb[:,:,1]*1.5)&(rgb[:,:,0]>rgb[:,:,2]*1.4))]:
  p=xyz[m];p=p[p[:,2]>.012];print(col,'q',np.round(np.quantile(p,[.01,.05,.5,.95,.99],axis=0),3));
  bins=np.linspace(np.quantile(p[:,0],.05),np.quantile(p[:,0],.95),5)
  for a,b in zip(bins[:-1],bins[1:]):
   s=p[(p[:,0]>=a)&(p[:,0]<b)];print(round((a+b)/2,3),len(s),np.round(np.median(s[:,1:],axis=0),3) if len(s) else [])
